import csv
import io
import re
from typing import List, Dict, Any


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    expected_width = 3
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    records = []

    for record in reader:
        if not record or all(not value.strip() for value in record):
            continue
        records.append([value for value in record])

    if not records:
        return {"columns": [f"column_{i + 1}" for i in range(expected_width)], "rows": []}

    date_pattern = re.compile(r"^\s*\d{1,4}[/-]\d{1,2}[/-]\d{1,4}\s*$")
    time_pattern = re.compile(r"^\s*\d{1,2}:\d{2}(?::\d{2})?(?:\s*[APap][Mm])?\s*$")
    number_pattern = re.compile(r"^\s*(?:[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?|nan|inf(?:inity)?)\s*$", re.I)

    def has_data_value(record: List[str]) -> bool:
        return any(
            date_pattern.match(value)
            or time_pattern.match(value)
            or number_pattern.match(value)
            for value in record
        )

    first = records[0]
    has_header = (
        len(first) == expected_width
        and len(records) > 1
        and not has_data_value(first)
        and has_data_value(records[1])
    )

    if has_header:
        columns = [value.strip() or f"column_{i + 1}" for i, value in enumerate(first)]
        data_records = records[1:]
    else:
        data_records = records
        columns = []

    width = max(expected_width, len(columns), max((len(record) for record in data_records), default=0))

    if not columns:
        columns = [f"column_{i + 1}" for i in range(width)]
    elif len(columns) < width:
        columns.extend(f"column_{i + 1}" for i in range(len(columns), width))

    rows = []
    for record in data_records:
        normalized = record[:width]
        if len(normalized) < width:
            normalized.extend([""] * (width - len(normalized)))
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
